    if ($c.str.getByteLength($c.util.getComponent('ipt_encrypChrgEmail1').getValue().trim()) > 0 && $c.str.getByteLength($c.util.getComponent('ipt_encrypChrgEmail2').getValue().trim()) > 0) {
        $c.util.getComponent('dma_chkFrmReq').set('encrypChrgEmail', $c.util.getComponent('ipt_encrypChrgEmail1').getValue()+ "@" + $c.util.getComponent('ipt_encrypChrgEmail2').getValue());
    }
    if (!await scwin.dataValidation()) {
        return;
    }
    if (!$c.str.isEmail($c.util.getComponent('dma_chkFrmReq').get('encrypChrgEmail'))) {
        await $c.win.alert("이메일 주소 형식이 아닙니다.");
        $c.util.getComponent("ipt_encrypChrgEmail1").focus();
        return;
    }
    if (!!!(($c.util.getComponent('dlt_files')) && ($c.util.getComponent('dlt_files')).getRowCount && ($c.util.getComponent('dlt_files')).getRowCount() > 0)) {
        return;
    }
    const totFileSize = (Math.round(((($c.util.getComponent('dlt_files')) && ($c.util.getComponent('dlt_files')).getRowCount) ? Array.from({ length: ($c.util.getComponent('dlt_files')).getRowCount() }, function (x, i) { return Number(($c.util.getComponent('dlt_files')).getCellData(i, 'FILE_SIZE')) || 0; }).reduce(function (a, b) { return a + b; }, 0) : 0) / (1024 * 1024) * 100) / 100);
    if (totFileSize > 100) {
        await $c.win.alert("전체 첨부파일의 크기는 최대 100MB까지 허용됩니다.\n현재 크기 = " + totFileSize + "MB");
        return;
    }
    if (document.infoIframe.getComponentById("perInfo1").checked === false) {
        await $c.win.alert("개인정보 처리방침에 동의해 주세요.");
        console.error("[sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완"); /* unresolved-target intent:set_focus — {target}.focus({args}) */
        return;
    }
    if (document.infoIframe.getComponentById("perInfo2").checked === false) {
        await $c.win.alert("개인정보 수집 및 이용에 동의해 주세요.");
        console.error("[sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완"); /* unresolved-target intent:set_focus — {target}.focus({args}) */
        return;
    }
    if (document.infoIframe.getComponentById("perInfo3").checked === false) {
        await $c.win.alert("표준코드 부여 및 관리 서비스 이용 약관에 동의해 주세요.");
        console.error("[sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완"); /* unresolved-target intent:set_focus — {target}.focus({args}) */
        return;
    }
    if (await $c.win.confirm("입력된 이메일을 확인해주세요.\n\n이메일 : " + $c.util.getComponent('ipt_encrypChrgEmail').getValue() + "\n\n신청하시겠습니까?")) {
        scwin.reg_button.setStyle("display", "none");
        fm.target = '_self';
        fm.method = 'post';
        fm.action = '/corp/corp.do?method=corpNewReqSave';
        await scwin.tx_chk_frm();
    }
    /* sdd-asis-lifecycle:end */
};


